/* eslint-disable no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var defineProperty = require( '@stdlib/utils/define-property' );
var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var setReadOnlyAccessor = require( '@stdlib/utils/define-nonenumerable-read-only-accessor' );
var isPositive = require( '@stdlib/assert/is-positive-number' ).isPrimitive;
var entropy = require( '@stdlib/stats/base/dists/halfnormal/entropy' );
var kurtosis = require( '@stdlib/stats/base/dists/halfnormal/kurtosis' );
var mean = require( '@stdlib/stats/base/dists/halfnormal/mean' );
var median = require( '@stdlib/stats/base/dists/halfnormal/median' );
var mode = require( '@stdlib/stats/base/dists/halfnormal/mode' );
var skewness = require( '@stdlib/stats/base/dists/halfnormal/skewness' );
var stdev = require( '@stdlib/stats/base/dists/halfnormal/stdev' );
var variance = require( '@stdlib/stats/base/dists/halfnormal/variance' );
var cdf = require( '@stdlib/stats/base/dists/halfnormal/cdf' );
var logcdf = require( '@stdlib/stats/base/dists/halfnormal/logcdf' );
var logpdf = require( '@stdlib/stats/base/dists/halfnormal/logpdf' );
var mgf = require( '@stdlib/stats/base/dists/halfnormal/mgf' );
var pdf = require( '@stdlib/stats/base/dists/halfnormal/pdf' );
var quantile = require( '@stdlib/stats/base/dists/halfnormal/quantile' );
var format = require( '@stdlib/string/format' );


// FUNCTIONS //

/**
* Evaluates the cumulative distribution function (CDF).
*
* @private
* @param {number} x - input value
* @returns {Probability} evaluated CDF
*/
function halfnormalCDF( x ) {
	return cdf( x, this.sigma );
}

/**
* Evaluates the natural logarithm of the cumulative distribution function (CDF).
*
* @private
* @param {number} x - input value
* @returns {number} evaluated logCDF
*/
function halfnormalLogCDF( x ) {
	return logcdf( x, this.sigma );
}

/**
* Evaluates the natural logarithm of the probability density function (PDF).
*
* @private
* @param {number} x - input value
* @returns {number} evaluated logPDF
*/
function halfnormalLogPDF( x ) {
	return logpdf( x, this.sigma );
}

/**
* Evaluates the moment-generating function (MGF).
*
* @private
* @param {number} t - input value
* @returns {number} evaluated MGF
*/
function halfnormalMGF( t ) {
	return mgf( t, this.sigma );
}

/**
* Evaluates the probability density function (PDF).
*
* @private
* @param {number} x - input value
* @returns {number} evaluated PDF
*/
function halfnormalPDF( x ) {
	return pdf( x, this.sigma );
}

/**
* Evaluates the quantile function.
*
* @private
* @param {Probability} p - input probability
* @returns {number} evaluated quantile function
*/
function halfnormalQuantile( p ) {
	return quantile( p, this.sigma );
}


// MAIN //

/**
* Half-normal distribution constructor.
*
* @constructor
* @param {PositiveNumber} [sigma=1.0] - scale parameter
* @throws {TypeError} `sigma` must be a positive number
* @returns {HalfNormal} distribution instance
*
* @example
* var halfnormal = new HalfNormal( 1.0 );
*
* var y = halfnormal.cdf( 1.5 );
* // returns ~0.866
*
* var v = halfnormal.mean;
* // returns ~0.798
*/
function HalfNormal() {
	var sigma;
	if ( !(this instanceof HalfNormal) ) {
		if ( arguments.length === 0 ) {
			return new HalfNormal();
		}
		return new HalfNormal( arguments[ 0 ] );
	}
	if ( arguments.length ) {
		sigma = arguments[ 0 ];
		if ( !isPositive( sigma ) ) {
			throw new TypeError( format( 'invalid argument. Scale parameter must be a positive number. Value: `%s`.', sigma ) );
		}
	} else {
		sigma = 1.0;
	}
	defineProperty( this, 'sigma', {
		'configurable': false,
		'enumerable': true,
		'get': function get() {
			return sigma;
		},
		'set': function set( value ) {
			if ( !isPositive( value ) ) {
				throw new TypeError( format( 'invalid assignment. Must be a positive number. Value: `%s`.', value ) );
			}
			sigma = value;
		}
	});
	return this;
}

/**
* Half-normal distribution differential entropy.
*
* @name entropy
* @memberof HalfNormal.prototype
* @type {number}
* @see [differential entropy]{@link https://en.wikipedia.org/wiki/Entropy_%28information_theory%29}
*
* @example
* var halfnormal = new HalfNormal( 4.0 );
*
* var v = halfnormal.entropy;
* // returns 2.112085713764618
*/
setReadOnlyAccessor( HalfNormal.prototype, 'entropy', function get() {
	return entropy( this.sigma );
});

/**
* Half-normal distribution excess kurtosis.
*
* @name kurtosis
* @memberof HalfNormal.prototype
* @type {number}
* @see [kurtosis]{@link https://en.wikipedia.org/wiki/Kurtosis}
*
* @example
* var halfnormal = new HalfNormal( 4.0 );
*
* var v = halfnormal.kurtosis;
* // returns ~0.869
*/
setReadOnlyAccessor( HalfNormal.prototype, 'kurtosis', function get() {
	return kurtosis( this.sigma );
});

/**
* Half-normal distribution expected value.
*
* @name mean
* @memberof HalfNormal.prototype
* @type {number}
* @see [expected value]{@link https://en.wikipedia.org/wiki/Expected_value}
*
* @example
* var halfnormal = new HalfNormal( 4.0 );
*
* var v = halfnormal.mean;
* // returns 3.1915382432114616
*/
setReadOnlyAccessor( HalfNormal.prototype, 'mean', function get() {
	return mean( this.sigma );
});

/**
* Half-normal distribution median.
*
* @name median
* @memberof HalfNormal.prototype
* @type {number}
* @see [median]{@link https://en.wikipedia.org/wiki/Median}
*
* @example
* var halfnormal = new HalfNormal( 4.0 );
*
* var v = halfnormal.median;
* // returns ~2.698
*/
setReadOnlyAccessor( HalfNormal.prototype, 'median', function get() {
	return median( this.sigma );
});

/**
* Half-normal distribution mode.
*
* @name mode
* @memberof HalfNormal.prototype
* @type {number}
* @see [mode]{@link https://en.wikipedia.org/wiki/Mode_%28statistics%29}
*
* @example
* var halfnormal = new HalfNormal( 4.0 );
*
* var v = halfnormal.mode;
* // returns 0.0
*/
setReadOnlyAccessor( HalfNormal.prototype, 'mode', function get() {
	return mode( this.sigma );
});

/**
* Half-normal distribution skewness.
*
* @name skewness
* @memberof HalfNormal.prototype
* @type {number}
* @see [skewness]{@link https://en.wikipedia.org/wiki/Skewness}
*
* @example
* var halfnormal = new HalfNormal( 4.0 );
*
* var v = halfnormal.skewness;
* // returns ~0.995
*/
setReadOnlyAccessor( HalfNormal.prototype, 'skewness', function get() {
	return skewness( this.sigma );
});

/**
* Half-normal distribution standard deviation.
*
* @name stdev
* @memberof HalfNormal.prototype
* @type {PositiveNumber}
* @see [standard deviation]{@link https://en.wikipedia.org/wiki/Standard_deviation}
*
* @example
* var halfnormal = new HalfNormal( 4.0 );
*
* var v = halfnormal.stdev;
* // returns ~2.411
*/
setReadOnlyAccessor( HalfNormal.prototype, 'stdev', function get() {
	return stdev( this.sigma );
});

/**
* Half-normal distribution variance.
*
* @name variance
* @memberof HalfNormal.prototype
* @type {PositiveNumber}
* @see [variance]{@link https://en.wikipedia.org/wiki/Variance}
*
* @example
* var halfnormal = new HalfNormal( 4.0 );
*
* var v = halfnormal.variance;
* // returns ~5.814
*/
setReadOnlyAccessor( HalfNormal.prototype, 'variance', function get() {
	return variance( this.sigma );
});

/**
* Evaluates the cumulative distribution function (CDF).
*
* @name cdf
* @memberof HalfNormal.prototype
* @type {Function}
* @param {number} x - input value
* @returns {number} evaluated CDF
* @see [cdf]{@link https://en.wikipedia.org/wiki/Cumulative_distribution_function}
*
* @example
* var halfnormal = new HalfNormal( 2.0 );
*
* var v = halfnormal.cdf( 0.5 );
* // returns 0.19741265136584743
*/
setReadOnly( HalfNormal.prototype, 'cdf', halfnormalCDF );

/**
* Evaluates the natural logarithm of the cumulative distribution function (CDF).
*
* @name logcdf
* @memberof HalfNormal.prototype
* @type {Function}
* @param {number} x - input value
* @returns {number} evaluated logCDF
* @see [cdf]{@link https://en.wikipedia.org/wiki/Cumulative_distribution_function}
*
* @example
* var halfnormal = new HalfNormal( 2.0 );
*
* var v = halfnormal.logcdf( 0.5 );
* // returns -1.622459064037205
*/
setReadOnly( HalfNormal.prototype, 'logcdf', halfnormalLogCDF );

/**
* Evaluates the natural logarithm of the probability density function (PDF).
*
* @name logpdf
* @memberof HalfNormal.prototype
* @type {Function}
* @param {number} x - input value
* @returns {number} evaluated logPDF
* @see [pdf]{@link https://en.wikipedia.org/wiki/Probability_density_function}
*
* @example
* var halfnormal = new HalfNormal( 2.0 );
*
* var v = halfnormal.logpdf( 0.8 );
* // returns ~-1.0
*/
setReadOnly( HalfNormal.prototype, 'logpdf', halfnormalLogPDF );

/**
* Evaluates the moment-generating function (MGF).
*
* @name mgf
* @memberof HalfNormal.prototype
* @type {Function}
* @param {number} t - input value
* @returns {number} evaluated MGF
* @see [mgf]{@link https://en.wikipedia.org/wiki/Moment-generating_function}
*
* @example
* var halfnormal = new HalfNormal( 2.0 );
*
* var v = halfnormal.mgf( 0.5 );
* // returns 2.7742859576700094
*/
setReadOnly( HalfNormal.prototype, 'mgf', halfnormalMGF );

/**
* Evaluates the probability density function (PDF).
*
* @name pdf
* @memberof HalfNormal.prototype
* @type {Function}
* @param {number} x - input value
* @returns {number} evaluated PDF
* @see [pdf]{@link https://en.wikipedia.org/wiki/Probability_density_function}
*
* @example
* var halfnormal = new HalfNormal( 2.0 );
*
* var v = halfnormal.pdf( 0.8 );
* // returns ~0.368
*/
setReadOnly( HalfNormal.prototype, 'pdf', halfnormalPDF );

/**
* Evaluates the quantile function.
*
* @name quantile
* @memberof HalfNormal.prototype
* @type {Function}
* @param {Probability} p - input probability
* @returns {number} evaluated quantile function
* @see [quantile function]{@link https://en.wikipedia.org/wiki/Quantile_function}
*
* @example
* var halfnormal = new HalfNormal( 2.0 );
*
* var v = halfnormal.quantile( 0.5 );
* // returns ~1.349
*/
setReadOnly( HalfNormal.prototype, 'quantile', halfnormalQuantile );


// EXPORTS //

module.exports = HalfNormal;
